// Serves videos for cdn-yral-sfw.yral.com.
//
// The mobile app builds video URLs itself and never asks a service for them:
//
//     https://cdn-yral-sfw.yral.com/{oauth_subject}/{video_id}.mp4
//     https://cdn-yral-sfw.yral.com/{oauth_subject}/{video_id}-thumbnail.png
//
// Videos generated by the new agent service are written to the Storj bucket
// `yral-videos`. Everything older lives in the Hetzner bucket this hostname has
// always pointed at. Rather than move the old catalogue — which we cannot
// verify is mirrored anywhere — this worker looks in Storj first and falls back
// to Hetzner, so old videos keep playing untouched.
//
// Storj is read with a signed request rather than a public link so the bucket
// stays private. Both origins are plain S3, so range requests (video seeking)
// pass straight through: the app's player asks for byte ranges and gets 206s.
//
// Deploy:
//   wrangler secret put STORJ_ACCESS_KEY_ID
//   wrangler secret put STORJ_SECRET_ACCESS_KEY
//   wrangler deploy
// then route cdn-yral-sfw.yral.com/* to this worker.

const STORJ_HOST = "gateway.storjshare.io";
const STORJ_BUCKET = "yral-videos";
const HETZNER_HOST = "yral-sfw.hel1.your-objectstorage.com";

// Storj's S3 gateway accepts any region; us-east-1 is the conventional default.
const REGION = "us-east-1";
const SERVICE = "s3";

export default {
  async fetch(request, env) {
    // Only reads. A CDN hostname should never accept writes.
    if (request.method !== "GET" && request.method !== "HEAD") {
      return new Response("Method not allowed", { status: 405 });
    }

    const objectKey = new URL(request.url).pathname.replace(/^\//, "");
    if (!objectKey) return new Response("Not found", { status: 404 });

    const fromStorj = await fetchFromStorj(objectKey, request, env);
    // 2xx covers 200 and 206 (a range request, which is how video seeking works).
    if (fromStorj.status >= 200 && fromStorj.status < 300) return fromStorj;

    // Anything else — usually 404 for a video predating the new service —
    // falls back to the bucket this hostname served before.
    return fetch(`https://${HETZNER_HOST}/${objectKey}`, request);
  },
};

async function fetchFromStorj(objectKey, request, env) {
  const now = new Date();
  const amzDate = now.toISOString().replace(/[:-]|\.\d{3}/g, "");
  const dateStamp = amzDate.slice(0, 8);

  // Every path segment is encoded, but the separators are not — that is what
  // AWS calls the "canonical URI", and Storj follows the same rule.
  const canonicalPath =
    "/" + [STORJ_BUCKET, ...objectKey.split("/")].map(encodeURIComponent).join("/");

  // A GET has no body, so the payload hash is the hash of the empty string.
  const payloadHash = await sha256Hex("");

  const canonicalRequest = [
    "GET",
    canonicalPath,
    "",
    `host:${STORJ_HOST}`,
    `x-amz-content-sha256:${payloadHash}`,
    `x-amz-date:${amzDate}`,
    "",
    "host;x-amz-content-sha256;x-amz-date",
    payloadHash,
  ].join("\n");

  const scope = `${dateStamp}/${REGION}/${SERVICE}/aws4_request`;
  const stringToSign = [
    "AWS4-HMAC-SHA256",
    amzDate,
    scope,
    await sha256Hex(canonicalRequest),
  ].join("\n");

  // The signing key is derived by chaining HMACs over date, region and service,
  // so a leaked signature is only usable for that one day and scope.
  let key = new TextEncoder().encode("AWS4" + env.STORJ_SECRET_ACCESS_KEY);
  for (const part of [dateStamp, REGION, SERVICE, "aws4_request"]) {
    key = await hmac(key, part);
  }
  const signature = toHex(await hmac(key, stringToSign));

  const headers = new Headers({
    "x-amz-content-sha256": payloadHash,
    "x-amz-date": amzDate,
    Authorization:
      `AWS4-HMAC-SHA256 Credential=${env.STORJ_ACCESS_KEY_ID}/${scope}, ` +
      "SignedHeaders=host;x-amz-content-sha256;x-amz-date, " +
      `Signature=${signature}`,
  });
  // Forward the player's range request untouched so seeking still works. Range
  // is deliberately NOT signed — S3 treats it as an unsigned header.
  const range = request.headers.get("Range");
  if (range) headers.set("Range", range);

  return fetch(`https://${STORJ_HOST}${canonicalPath}`, {
    method: request.method,
    headers,
  });
}

async function sha256Hex(text) {
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(text));
  return toHex(digest);
}

async function hmac(keyBytes, message) {
  const key = await crypto.subtle.importKey(
    "raw", keyBytes, { name: "HMAC", hash: "SHA-256" }, false, ["sign"],
  );
  return crypto.subtle.sign("HMAC", key, new TextEncoder().encode(message));
}

function toHex(buffer) {
  return [...new Uint8Array(buffer)].map((b) => b.toString(16).padStart(2, "0")).join("");
}
